import sys

s = sys.stdin.read().split()[0]
MOD = 1000000007

def count(i):
    if i == len(s):
        return 1
    if s[i] == '0':
        return 0
    total = count(i + 1)
    if i + 1 < len(s) and 10 <= int(s[i:i + 2]) <= 26:
        total += count(i + 2)
    return total

print(count(0) % MOD)

